gated_delta_recurrence_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void gated_delta_recurrence_kernel(
    const float* __restrict__ q,      // (B, L, H, Dk)
    const float* __restrict__ k,      // (B, L, H, Dk)
    const float* __restrict__ v,      // (B, L, H, Dv)
    const float* __restrict__ alpha,  // (B, L, H)
    const float* __restrict__ beta,   // (B, L, H)
    float* __restrict__ o,            // (B, L, H, Dv)
    int B, int L, int H, int Dk, int Dv
) {
    // blockIdx.x = head index (0 to H-1)
    // blockIdx.y = batch index (0 to B-1)
    // threadIdx.x = row index of S (0 to Dv-1)

    int h = blockIdx.x;
    int b = blockIdx.y;
    int i = threadIdx.x; // row of S

    if (i >= Dv) return;

    // Allocate S row in shared memory or registers? 
    // Dk = 128, Dv = 128. 
    // If we have 128 threads, each thread can keep its own row of S in registers!
    // 128 floats in registers is 128 * 4 = 512 bytes.
    // MI300X has many registers. This should be fine.

    float s_row[128]; // Assuming Dk <= 128
    for (int j = 0; j < Dk; ++j) {
        s_row[j] = 0.0f;
    }

    // Shared memory for k_t and q_t to be accessed by all threads in the block
    __shared__ float k_t_shared[128];
    __shared__ float q_t_shared[128];

    for (int t = 0; t < L; ++t) {
        // Load k_t, q_t into shared memory
        if (i < Dk) {
            k_t_shared[i] = k[((b * L + t) * H + h) * Dk + i];
            q_t_shared[i] = q[((b * L + t) * H + h) * Dk + i];
        }

        // Load v_t, alpha_t, beta_t
        float v_ti = v[((b * L + t) * H + h) * Dv + i];
        float alpha_t = alpha[(b * L + t) * H + h];
        float beta_t = beta[(b * L + t) * H + h];

        __syncthreads();

        // 1. Compute S_k = S @ k_t
        float sk_i = 0.0f;
        for (int j = 0; j < Dk; ++j) {
            sk_i += s_row[j] * k_t_shared[j];
        }

        // 2. Compute error = S_k - v_t
        float error_i = sk_i - v_ti;

        // 3. Update S: S = alpha * S - beta * error @ k_t^T
        for (int j = 0; j < Dk; ++j) {
            s_row[j] = alpha_t * s_row[j] - beta_t * error_i * k_t_shared[j];
        }

        // 4. Compute o_t = S_t @ q_t
        float ot_i = 0.0f;
        for (int j = 0; j < Dk; ++j) {
            ot_i += s_row[j] * q_t_shared[j];
        }

        // Write o_t
        o[((b * L + t) * H + h) * Dv + i] = ot_i;

        __syncthreads(); // Ensure next k_t, q_t load doesn't overwrite
    }
}

torch::Tensor gated_delta_recurrence_hip(
    torch::Tensor q, torch::Tensor k, torch::Tensor v, 
    torch::Tensor alpha, torch::Tensor beta
) {
    int B = q.size(0);
    int L = q.size(1);
    int H = q.size(2);
    int Dk = q.size(3);
    int Dv = v.size(3);

    auto o = torch::empty_like(v);

    dim3 blocks(H, B);
    dim3 threads(Dv);

    gated_delta_recurrence_kernel<<<blocks, threads>>>(
        q.data_ptr<float>(), k.data_ptr<float>(), v.data_ptr<float>(),
        alpha.data_ptr<float>(), beta.data_ptr<float>(),
        o.data_ptr<float>(), B, L, H, Dk, Dv
    );

    return o;
}
"""

gated_delta_recurrence_lib = load_inline(
    name="gated_delta_recurrence",
    cpp_sources=gated_delta_recurrence_source,
    functions=["gated_delta_recurrence_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_heads: int,
        head_dim_qk: int,
        head_dim_v: int,
        use_short_conv: bool = True,
        conv_kernel_size: int = 4,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_heads
        self.head_dim_qk = head_dim_qk
        self.head_dim_v = head_dim_v
        self.use_short_conv = use_short_conv

        self.q_proj = nn.Linear(hidden_size, num_heads * head_dim_qk, bias=False)
        self.k_proj = nn.Linear(hidden_size, num_heads * head_dim_qk, bias=False)
        self.v_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=False)

        self.a_proj = nn.Linear(hidden_size, num_heads, bias=True)
        self.b_proj = nn.Linear(hidden_size, num_heads, bias=True)

        self.o_proj = nn.Linear(num_heads * head_dim_v, hidden_size, bias=False)

        if use_short_conv:
            self.q_conv = nn.Conv1d(
                num_heads * head_dim_qk, num_heads * head_dim_qk,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_qk,
                padding=conv_kernel_size - 1
            )
            self.k_conv = nn.Conv1d(
                num_heads * head_dim_qk, num_heads * head_dim_qk,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_qk,
                padding=conv_kernel_size - 1
            )
            self.v_conv = nn.Conv1d(
                num_heads * head_dim_v, num_heads * head_dim_v,
                kernel_size=conv_kernel_size, groups=num_heads * head_dim_v,
                padding=conv_kernel_size - 1
            )

        self.g_proj = nn.Linear(hidden_size, num_heads * head_dim_v, bias=False)
        self.o_norm = nn.LayerNorm(head_dim_v)
        self.scale = head_dim_qk ** -0.5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, seq_len, _ = x.shape

        q = self.q_proj(x)
        k = self.k_proj(x)
        v = self.v_proj(x)

        if self.use_short_conv:
            q = F.silu(self.q_conv(q.transpose(1, 2))[:, :, :seq_len].transpose(1, 2))
            k = F.silu(self.k_conv(k.transpose(1, 2))[:, :, :seq_len].transpose(1, 2))
            v = F.silu(self.v_conv(v.transpose(1, 2))[:, :, :seq_len].transpose(1, 2))

        q = q.view(batch_size, seq_len, self.num_heads, self.head_dim_qk)
        k = k.view(batch_size, seq_len, self.num_heads, self.head_dim_qk) * self.scale
        v = v.view(batch_size, seq_len, self.num_heads, self.head_dim_v)

        alpha = torch.sigmoid(self.a_proj(x))
        beta = torch.sigmoid(self.b_proj(x))

        # HIP kernel for recurrence
        o = gated_delta_recurrence_lib.gated_delta_recurrence_hip(q, k, v, alpha, beta)

        o = self.o_norm(o)
        g = torch.sigmoid(self.g_proj(x)).view(batch_size, seq_len, self.num_heads, self.head_dim_v)
        o = (o * g).reshape(batch_size, seq_len, self.num_heads * self.head_dim_v)
        o = self.o_proj(o)

        return o

import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

gemm_int4_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <hip/hip_fp16.h>

__global__ void gemm_int4_kernel(
    const __half* __restrict__ A,          // (M, K)
    const uint8_t* __restrict__ B_packed,  // (N, K/2)
    const __half* __restrict__ scales,     // (N, K/G)
    __half* __restrict__ C,                 // (M, N)
    int M, int N, int K, int group_size
) {
    int row = blockIdx.y * blockDim.y + threadIdx.y; // M index
    int col = blockIdx.x * blockDim.x + threadIdx.x; // N index

    if (row < M && col < N) {
        float sum = 0.0f;
        int num_groups = K / group_size;

        for (int g = 0; g < num_groups; ++g) {
            __half scale = scales[col * num_groups + g];
            int k_start = g * group_size;

            // For each group, we iterate over group_size elements.
            // Since we have INT4, 2 weights per byte, we process 2 weights at a time.
            for (int k_offset = 0; k_offset < group_size; k_offset += 2) {
                int k = k_start + k_offset;

                uint8_t packed_val = B_packed[col * (K / 2) + (k / 2)];

                // Low nibble (first weight)
                float w0 = (float)(packed_val & 0x0F) - 8.0f;
                sum += (float)A[row * K + k] * (float)scale * w0;

                // High nibble (second weight)
                float w1 = (float)(packed_val >> 4) - 8.0f;
                sum += (float)A[row * K + k + 1] * (float)scale * w1;
            }
        }
        C[row * N + col] = (__half)sum;
    }
}

// More optimized version with tiling in shared memory
__global__ void gemm_int4_tiled_kernel(
    const __half* __restrict__ A,          // (M, K)
    const uint8_t* __restrict__ B_packed,  // (N, K/2)
    const __half* __restrict__ scales,     // (N, K/G)
    __half* __restrict__ C,                 // (M, N)
    int M, int N, int K, int group_size
) {
    // Tiling parameters
    const int BM = 32;
    const int BN = 64;
    const int BK = 32;

    __shared__ __half sA[BM][BK];
    __shared__ __half sB[BN][BK];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Output element indices
    int row_start = by * BM;
    int col_start = bx * BN;

    float acc[BN / 32][BM / 32]; // Each thread could handle more, but let's keep it simple
    // Let's simplify and have each thread compute one output for now
    // for simplicity, let's use 16x16 threads per block, each computing 2x4 outputs.
    // BM=32, BN=64, so we need 32*64 = 2048 elements.
    // With 16x16 = 256 threads, each thread handles 2048/256 = 8 elements.
}

// Actually, the simple kernel is too slow. Let's write a better one.
// We'll use a standard tiling approach.

__global__ void gemm_int4_v2(
    const __half* __restrict__ A,
    const uint8_t* __restrict__ B_packed,
    const __half* __restrict__ scales,
    __half* __restrict__ C,
    int M, int N, int K, int group_size
) {
    // Each block handles 64x64 tile of C
    // Threads: 16x16 = 256
    // Each thread handles 4x4 = 16 elements of C

    int row_start = blockIdx.y * 64;
    int col_start = blockIdx.x * 64;

    float acc[4][4];
    for(int i=0; i<4; i++) for(int j=0; j<4; j++) acc[i][j] = 0.0f;

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    for (int k_tile = 0; k_tile < K; k_tile += 32) {
        // Shared memory for tiles
        __shared__ __half sA[64][32];
        __shared__ __half sB[64][32];

        // Collaborative load A into shared memory
        // A is (M, K), tile is (64, 32). 64*32 = 2048 elements.
        // 256 threads, each loads 8 elements.
        for (int i = 0; i < 8; ++i) {
            int idx = (ty * 16 + tx) * 8 + i;
            int r = idx / 32;
            int c = idx % 32;
            if (row_start + r < M && k_tile + c < K)
                sA[r][c] = A[(row_start + r) * K + (k_tile + c)];
            else
                sA[r][c] = (__half)0.0f;
        }

        // Collaborative load and dequantize B into shared memory
        // B_packed is (N, K/2), dequantized tile is (64, 32).
        // Each byte of B_packed gives 2 elements.
        // To fill 64x32 elements, we need 64*16 bytes from B_packed.
        // 64*16 = 1024 bytes. 256 threads, each loads 4 bytes and dequantizes.
        int num_groups = K / group_size;
        for (int i = 0; i < 4; ++i) {
            int idx = (ty * 16 + tx) * 4 + i; // idx in [0, 1023]
            int r = idx / 16; // row in dequantized tile (0-63)
            int c_half = idx % 16; // column in B_packed (0-15)

            int n_idx = col_start + r;
            int k_idx = k_tile + c_half * 2;

            if (n_idx < N && k_idx < K) {
                uint8_t packed_val = B_packed[n_idx * (K / 2) + (k_idx / 2)];
                __half scale = scales[n_idx * num_groups + (k_idx / group_size)];

                sB[r][c_half * 2] = (__half)((float)scale * ((float)(packed_val & 0x0F) - 8.0f));
                sB[r][c_half * 2 + 1] = (__half)((float)scale * ((float)(packed_val >> 4) - 8.0f));
            } else {
                sB[r][c_half * 2] = (__half)0.0f;
                sB[r][c_half * 2 + 1] = (__half)0.0f;
            }
        }

        __syncthreads();

        // Compute tile
        for (int k = 0; k < 32; ++k) {
            for (int i = 0; i < 4; ++i) {
                for (int j = 0; j < 4; ++j) {
                    acc[i][j] += (float)sA[ty * 4 + i][k] * (float)sB[tx * 4 + j][k];
                }
            }
        }

        __syncthreads();
    }

    // Store result
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            int r = row_start + ty * 4 + i;
            int c = col_start + tx * 4 + j;
            if (r < M && c < N) {
                C[r * N + c] = (__half)acc[i][j];
            }
        }
    }
}

torch::Tensor gemm_int4_hip(torch::Tensor x, torch::Tensor weight_packed, torch::Tensor scales, int group_size) {
    auto M = x.size(0) * x.size(1);
    auto K = x.size(2);
    auto N = weight_packed.size(0);

    auto x_reshaped = x.reshape({M, K});
    auto out = torch::empty({M, N}, x.options());

    dim3 block(16, 16);
    dim3 grid((N + 63) / 64, (M + 63) / 64);

    gemm_int4_v2<<<grid, block>>>(
        (__half*)x_reshaped.data_ptr<at::Half>(),
        (uint8_t*)weight_packed.data_ptr<uint8_t>(),
        (__half*)scales.data_ptr<at::Half>(),
        (__half*)out.data_ptr<at::Half>(),
        M, N, K, group_size
    );

    return out.reshape({x.size(0), x.size(1), N});
}
"""

gemm_int4_module = load_inline(
    name="gemm_int4",
    cpp_sources=gemm_int4_cpp_source,
    functions=["gemm_int4_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, K: int, N: int, group_size: int = 128):
        super().__init__()
        self.K = K
        self.N = N
        self.group_size = group_size
        self.num_groups = K // group_size

        self.register_buffer(
            "weight_packed",
            torch.randint(0, 256, (N, K // 2), dtype=torch.uint8)
        )
        self.register_buffer(
            "scales",
            torch.randn(N, self.num_groups, dtype=torch.float16).abs() * 0.1
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return gemm_int4_module.gemm_int4_hip(x, self.weight_packed, self.scales, self.group_size)

