#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void reorder_tokens_kernel(
    const float* __restrict__ x,
    const int64_t* __restrict__ token_indices,
    const float* __restrict__ expert_weights,
    float* __restrict__ reordered_x,
    float* __restrict__ reordered_weights,
    int hidden_size,
    int num_token_instances
) {
    int instance_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (instance_idx < num_token_instances) {
        int64_t full_token_idx = token_indices[instance_idx];
        int token_idx = full_token_idx / 2; // Each token appears top_k=2 times. No, this is wrong.
        // The token_indices already contain the correct index into the flattened x.
    }
}
// Wait, let's reconsider the reordering.
// x: (num_tokens, hidden_size)
// expert_indices: (num_tokens, top_k)
// token_indices (after argsort): (num_tokens * top_k)
// So token_indices[i] is an index in [0, num_tokens * top_k - 1].
// The original token index is token_indices[i] / top_k.

__global__ void reorder_tokens_v2(
    const float* __restrict__ x,
    const int64_t* __restrict__ token_instance_indices,
    const float* __restrict__ weights_flat,
    float* __restrict__ reordered_x,
    float* __restrict__ reordered_weights,
    int hidden_size,
    int num_tokens,
    int top_k,
    int num_token_instances
) {
    int instance_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (instance_idx < num_token_instances) {
        int64_t instance_info_idx = token_instance_indices[instance_idx];
        int token_idx = instance_info_idx / top_k;

        // Copy x[token_idx] to reordered_x[instance_idx]
        const float* src_x = x + (int64_t)token_idx * hidden_size;
        float* dst_x = reordered_x + (int64_t)instance_idx * hidden_size;
        for (int i = 0; i < hidden_size; ++i) {
            dst_x[i] = src_x[i];
        }

        reordered_weights[instance_idx] = weights_flat[instance_info_idx];
    }
}

// Optimization: use more threads per token for reordering
__global__ void reorder_tokens_v3(
    const float* __restrict__ x,
    const int64_t* __restrict__ token_instance_indices,
    const float* __restrict__ weights_flat,
    float* __restrict__ reordered_x,
    float* __restrict__ reordered_weights,
    int hidden_size,
    int top_k,
    int num_token_instances
) {
    int instance_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (instance_idx < num_token_instances) {
        int64_t instance_info_idx = token_instance_indices[instance_idx];
        int token_idx = instance_info_idx / top_k;

        const float* src_x = x + (int64_t)token_idx * hidden_size;
        float* dst_x = reordered_x + (int64_t)instance_idx * hidden_size;

        for (int i = tid; i < hidden_size; i += blockDim.x) {
            dst_x[i] = src_x[i];
        }

        if (tid == 0) {
            reordered_weights[instance_idx] = weights_flat[instance_info_idx];
        }
    }
}

__global__ void fused_silu_mul_kernel(
    const float* __restrict__ gate_out,
    const float* __restrict__ up_out,
    float* __restrict__ out,
    int size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float g = gate_out[idx];
        float u = up_out[idx];
        // SiLU(g) * u = (g / (1 + exp(-g))) * u
        float silu_g = g / (1.0f + expf(-g));
        out[idx] = silu_g * u;
    }
}

__global__ void weighted_scatter_kernel(
    const float* __restrict__ expert_out,
    const int64_t* __restrict__ token_instance_indices,
    const float* __restrict__ reordered_weights,
    float* __restrict__ final_out,
    int hidden_size,
    int top_k,
    int num_token_instances
) {
    int instance_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (instance_idx < num_token_instances) {
        int64_t instance_info_idx = token_instance_indices[instance_idx];
        int token_idx = instance_info_idx / top_k;
        float weight = reordered_weights[instance_idx];

        const float* src = expert_out + (int64_t)instance_idx * hidden_size;
        float* dst = final_out + (int64_t)token_idx * hidden_size;

        for (int i = tid; i < hidden_size; i += blockDim.x) {
            // Using atomicAdd because multiple experts can contribute to the same token.
            atomicAdd(dst + i, src[i] * weight);
        }
    }
}

void reorder_tokens_hip(
    torch::Tensor x,
    torch::Tensor token_instance_indices,
    torch::Tensor weights_flat,
    torch::Tensor reordered_x,
    torch::Tensor reordered_weights,
    int top_k
) {
    int num_token_instances = token_instance_indices.size(0);
    int hidden_size = x.size(1);

    const int threads = 256;
    const int blocks = num_token_instances;

    reorder_tokens_v3<<<blocks, threads>>>(
        x.data_ptr<float>(),
        token_instance_indices.data_ptr<int64_t>(),
        weights_flat.data_ptr<float>(),
        reordered_x.data_ptr<float>(),
        reordered_weights.data_ptr<float>(),
