        top_k,
        num_token_instances
    );
}

void fused_silu_mul_hip(
    torch::Tensor gate_out,
    torch::Tensor up_out,
    torch::Tensor out
) {
    int size = gate_out.numel();
    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    fused_silu_mul_kernel<<<blocks, threads>>>(
        gate_out.data_ptr<float>(),
        up_out.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );
}

void weighted_scatter_hip(
    torch::Tensor expert_out,
    torch::Tensor token_instance_indices,
    torch::Tensor reordered_weights,
    torch::Tensor final_out,
    int top_k
) {
    int num_token_instances = token_instance_indices.size(0);
    int hidden_size = final_out.size(1);

    const int threads = 256;
    const int blocks = num_token_instances;

    weighted_scatter_kernel<<<blocks, threads>>>(
        expert_out.data_ptr<float>(),
        token_instance_indices.data_ptr<int64_t>(),
        reordered_weights.data_ptr<float>(),
        final_out.data_ptr<float>(),
        hidden_size,
        top_k,
        num_token_instances
    );
}
