class ModelNew(nn.Module):
    def __init__(self, hidden_size, intermediate_size, num_experts):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.num_experts = num_experts

        self.gate_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(num_experts, hidden_size, intermediate_size) * 0.02
        )

    def forward(self, x, expert_indices, expert_weights):
        batch_size, seq_len, hidden_size = x.shape
        top_k = expert_indices.shape[-1]
        num_tokens = batch_size * seq_len
        num_token_instances = num_tokens * top_k

        x_flat = x.view(num_tokens, hidden_size)
        expert_indices_flat = expert_indices.view(-1)
        expert_weights_flat = expert_weights.view(-1)

        # 1. Sort token-expert instances by expert_idx
        token_instance_indices = expert_indices_flat.argsort()
        sorted_expert_indices = expert_indices_flat[token_instance_indices]

        # 2. Reorder tokens and weights
        reordered_x = torch.empty(num_token_instances, hidden_size, device=x.device, dtype=x.dtype)
        reordered_weights = torch.empty(num_token_instances, device=x.device, dtype=x.dtype)

        moe_kernels.reorder_tokens_hip(
            x_flat,
            token_instance_indices,
            expert_weights_flat,
            reordered_x,
            reordered_weights,
            top_k
        )

        # 3. Find expert offsets
        expert_counts = torch.bincount(sorted_expert_indices, minlength=self.num_experts)
        expert_offsets = torch.cumsum(expert_counts, dim=0) - expert_counts

        # 4. Prepare output tensor
        final_output = torch.zeros(num_tokens, hidden_size, device=x.device, dtype=x.dtype)

        # 5. Loop through experts
        # We can optimize this by concatenating gate and up weights
        for i in range(self.num_experts):
            count = expert_counts[i].item()
            if count == 0:
                continue

            offset = expert_offsets[i].item()
            expert_tokens = reordered_x[offset : offset + count]

            # Gated GEMM
            # Expert gate_proj: (intermediate_size, hidden_size)
            # Expert up_proj: (intermediate_size, hidden_size)
            # Expert down_proj: (hidden_size, intermediate_size)

            gate_out = F.linear(expert_tokens, self.gate_proj[i])
            up_out = F.linear(expert_tokens, self.up_proj[i])

            # Fused SiLU and Mul
            intermediate = torch.empty(count, self.intermediate_size, device=x.device, dtype=x.dtype)
            moe_kernels.fused_silu_mul_hip(gate_out, up_out, intermediate)

            expert_out = F.linear(intermediate, self.down_proj[i])

            # Weighted Scatter
            # Instead of a full scatter kernel inside the loop, we can just do:
            # But we need to keep track of the original token indices for the scatter.
            # Let's use the weighted_scatter_hip but only for the current expert.

            # To use weighted_scatter_hip inside the loop, we need to pass the slice of token_instance_indices
            moe_kernels.weighted_scatter_hip(
                expert_out,
                token_instance_indices[offset : offset + count],
                reordered_weights[offset : offset + count],
                final_output,
                top_k
            )

        return final_output.view(batch_size, seq_len, hidden_size)

def get_inputs():
    batch_size = 4
    seq_len = 2048
    hidden_size = 4096
    num_experts = 8
    top_k = 2
    x = torch.randn(batch_size, seq_len, hidden_size).cuda()
    expert_indices = torch.stack([
        torch.randperm(num_experts)[:top_k]
        for _ in range(batch_size * seq_len)
    ]).view(batch_size, seq_len, top_k).cuda()
    expert_weights = F.softmax(torch.randn(batch_size, seq_len, top_k), dim=-1).cuda()
    return [x, expert_indices, expert_weights]

