quant_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <torch/extension.h>
#include <algorithm>

__global__ void amax_kernel(const __half* x, float* amax_out, int size) {
    extern __shared__ float shared_max[];
    int tid = threadIdx.x;
    int gid = blockIdx.x * blockDim.x + threadIdx.x;

    float local_max = 0.0f;
    while (gid < size) {
        local_max = fmaxf(local_max, fabsf(__half2float(x[gid])));
        gid += blockDim.x * gridDim.x;
    }

    shared_max[tid] = local_max;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_max[tid] = fmaxf(shared_max[tid], shared_max[tid + s]);
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicMax((int*)amax_out, __float_as_int(shared_max[0]));
    }
}

// Helper to convert float to FP8 (E4M3)
// Note: This is a simplified version. ROCm might have better ways.
// PyTorch's float8_e4m3fn has range [-448, 448].
__device__ inline uint8_t float_to_fp8_e4m3(float x) {
    // This is a placeholder. In a real implementation, we'd use proper bit manipulation.
    // For this optimization, we can also use PyTorch's casting if we don't want to write
    // the full conversion. Let's use PyTorch's own quantization for now if possible,
    // or just use a simple kernel for scaling.
    return 0; 
}

__global__ void quantize_kernel(const __half* x, uint8_t* out, float scale, float max_val, int size) {
    int gid = blockIdx.x * blockDim.x + threadIdx.x;
    if (gid < size) {
        float val = __half2float(x[gid]) * scale;
        val = fmaxf(fminf(val, max_val), -max_val);
        // We still need to convert val to the actual fp8 bit representation.
        // However, hipcc might not have an easy way to do this in a single instruction
        // without more headers. 
    }
}
