moe_kernels_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void swiglu_kernel(const float* gate_up, float* out, int num_rows, int intermediate_size) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < num_rows) {
        for (int i = 0; i < intermediate_size; ++i) {
            float g = gate_up[row * 2 * intermediate_size + i];
            float u = gate_up[row * 2 * intermediate_size + intermediate_size + i];
            out[row * intermediate_size + i] = (g / (1.0f + expf(-g))) * u;
        }
    }
}

__global__ void weighted_scatter_add_kernel(
    const float* expert_out_all,
    const float* weights,
    const int64_t* token_indices_all,
    float* output,
    int num_entries,
    int hidden_size
) {
    int entry_idx = blockIdx.x;
    int feature_idx = threadIdx.x;

    if (entry_idx < num_entries) {
        int64_t token_idx = token_indices_all[entry_idx];
        float weight = weights[entry_idx];
        const float* src = &expert_out_all[entry_idx * hidden_size];
        float* dst = &output[token_idx * hidden_size];

        for (int i = feature_idx; i < hidden_size; i += blockDim.x) {
            atomicAdd(&dst[i], src[i] * weight);
        }
    }
}

torch::Tensor swiglu_hip(torch::Tensor gate_up, int intermediate_size) {
    int num_rows = gate_up.size(0);
    auto out = torch::empty({num_rows, intermediate_size}, gate_up.options());
    const int block_size = 256;
    const int num_blocks = (num_rows + block_size - 1) / block_size;
    swiglu_kernel<<<num_blocks, block_size>>>(gate_up.data_ptr<float>(), out.data_ptr<float>(), num_rows, intermediate_size);
    return out;
}

void weighted_scatter_add_hip(
    torch::Tensor expert_out_all,
    torch::Tensor weights,
    torch::Tensor token_indices_all,
    torch::Tensor output
) {
    int num_entries = expert_out_all.size(0);
    int hidden_size = expert_out_all.size(1);
    const int block_size = 256;
    weighted_scatter_add_kernel<<<num_entries, block_size>>>(
        expert_out_all.data_ptr<float>(),
        weights.data_ptr<float>(),
        token_indices_all.data_ptr<int64_t>(),
        output.data_ptr<float>(),
        num_entries,
        hidden_size
    );
}
"""

