class MoEGate(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        n_routed_experts: int,
        num_experts_per_tok: int,
        n_group: int,
        topk_group: int,
        routed_scaling_factor: float = 1.0,
        norm_topk_prob: bool = True,
    ):
        super().__init__()
        self.top_k = num_experts_per_tok
        self.n_routed_experts = n_routed_experts
        self.n_group = n_group
        self.topk_group = topk_group
        self.routed_scaling_factor = routed_scaling_factor
        self.norm_topk_prob = norm_topk_prob

        self.weight = nn.Parameter(torch.empty(n_routed_experts, hidden_size))
        self.register_buffer("e_score_correction_bias", torch.zeros(n_routed_experts))
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

    def forward(self, hidden_states: torch.Tensor):
        bsz, seq_len, h = hidden_states.shape
        hidden_states = hidden_states.view(-1, h)

        logits = F.linear(hidden_states.float(), self.weight.float())
        scores = logits.sigmoid()

        scores_for_choice = scores + self.e_score_correction_bias.unsqueeze(0)

        # Simplified grouping/topk for speed in Python
        # (Though we could optimize this, it's usually not the bottleneck)
        tokens_count = bsz * seq_len
        group_scores = (
            scores_for_choice.view(tokens_count, self.n_group, -1)
            .topk(2, dim=-1)[0]
            .sum(dim=-1)
        )
        group_idx = torch.topk(group_scores, k=self.topk_group, dim=-1, sorted=False)[1]
        group_mask = torch.zeros_like(group_scores)
        group_mask.scatter_(1, group_idx, 1)

        score_mask = (
            group_mask.unsqueeze(-1)
            .expand(tokens_count, self.n_group, self.n_routed_experts // self.n_group)
            .reshape(tokens_count, -1)
        )
        tmp_scores = scores_for_choice.masked_fill(~score_mask.bool(), 0.0)
        _, topk_idx = torch.topk(tmp_scores, k=self.top_k, dim=-1, sorted=False)

        topk_weight = scores.gather(1, topk_idx)

        if self.top_k > 1 and self.norm_topk_prob:
            denominator = topk_weight.sum(dim=-1, keepdim=True) + 1e-20
            topk_weight = topk_weight / denominator
        topk_weight = topk_weight * self.routed_scaling_factor

        return topk_idx, topk_weight

class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        intermediate_size: int,
        n_routed_experts: int,
        num_experts_per_tok: int,
        n_group: int,
        topk_group: int,
        n_shared_experts: int = 0,
        routed_scaling_factor: float = 1.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.n_routed_experts = n_routed_experts
        self.num_experts_per_tok = num_experts_per_tok
        self.n_shared_experts = n_shared_experts

        self.gate_up_proj = nn.Parameter(
            torch.randn(n_routed_experts, 2 * intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(n_routed_experts, hidden_size, intermediate_size) * 0.02
        )

        self.gate = MoEGate(
            hidden_size=hidden_size,
            n_routed_experts=n_routed_experts,
            num_experts_per_tok=num_experts_per_tok,
            n_group=n_group,
            topk_group=topk_group,
            routed_scaling_factor=routed_scaling_factor,
        )

        if n_shared_experts > 0:
            shared_intermediate = intermediate_size * n_shared_experts
            self.shared_gate_proj = nn.Linear(hidden_size, shared_intermediate, bias=False)
            self.shared_up_proj = nn.Linear(hidden_size, shared_intermediate, bias=False)
            self.shared_down_proj = nn.Linear(shared_intermediate, hidden_size, bias=False)
        else:
            self.shared_gate_proj = None

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        identity = hidden_states
        orig_shape = hidden_states.shape
        bsz, seq_len, _ = orig_shape
        num_tokens = bsz * seq_len

        topk_idx, topk_weight = self.gate(hidden_states)
        hidden_states = hidden_states.view(num_tokens, self.hidden_size)

        flat_topk_idx = topk_idx.view(-1)
        flat_topk_weight = topk_weight.view(-1)

        # Expert grouping
        sorted_indices = torch.argsort(flat_topk_idx)
        sorted_topk_idx = flat_topk_idx[sorted_indices]
        counts = torch.bincount(sorted_topk_idx, minlength=self.n_routed_experts)
        offsets = torch.zeros(self.n_routed_experts + 1, dtype=torch.long, device=hidden_states.device)
        torch.cumsum(counts, dim=0, out=offsets[1:])

        token_indices_all = sorted_indices // self.num_experts_per_tok
        reordered_tokens = hidden_states.index_select(0, token_indices_all)

        y = torch.zeros_like(hidden_states)

        # Pre-allocate intermediate buffer for all experts
        # Size: (num_tokens * top_k, intermediate_size)
        # This is about 352 MB for the given input size.
        intermediate_all = torch.empty((num_tokens * self.num_experts_per_tok, self.intermediate_size), 
                                       device=hidden_states.device, dtype=hidden_states.dtype)

        # Expert loop: only 64 iterations, with combined gate/up proj
        for e in range(self.n_routed_experts):
            start, end = offsets[e], offsets[e+1]
            if start == end:
                continue

            # Combine gate and up proj into one GEMM
            gate_up_out = torch.matmul(reordered_tokens[start:end], self.gate_up_proj[e].t())
            # SwiGLU fused
            intermediate_all[start:end] = moe_kernels.swiglu_hip(gate_up_out, self.intermediate_size)

        # Expert loop for down projection
        # We can't easily fuse this without another loop
        expert_out_all = torch.empty((num_tokens * self.num_experts_per_tok, self.hidden_size), 
                                     device=hidden_states.device, dtype=hidden_states.dtype)
        for e in range(self.n_routed_experts):
            start, end = offsets[e], offsets[e+1]
            if start == end:
                continue
            expert_out_all[start:end] = torch.matmul(intermediate_all[start:end], self.down_proj[e].t())

        # Final weighted scatter-add
        moe_kernels.weighted_scatter_add_hip(
            expert_out_all,
            flat_topk_weight.index_select(0, sorted_indices),
            token_indices_all,
            y
        )

        y = y.view(*orig_shape)

        if self.shared_gate_proj is not None:
            shared_out = self.shared_down_proj(
                F.silu(self.shared_gate_proj(identity)) * self.shared_up_proj(identity)
            )
            y = y + shared_out

        return y

def get_inputs():
    return [torch.randn(4, 2048, 2048).cuda()]

