moe_gated_gemm_kernels_code = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void reorder_tokens_vectorized(
    const float* __restrict__ x,
    const int64_t* __restrict__ token_instance_indices,
    const float* __restrict__ weights_flat,
    float* __restrict__ reordered_x,
    float* __restrict__ reordered_weights,
    int hidden_size,
    int top_k,
    int num_token_instances
) {
    int instance_idx = blockIdx.x;
    int tid = threadIdx.x;

    int64_t instance_info_idx = token_instance_indices[instance_idx];
    int token_idx = (int)(instance_info_idx / top_k);

    const float4* src_x = (const float4*)(x + (int64_t)token_idx * hidden_size);
    float4* dst_x = (float4*)(reordered_x + (int64_t)instance_idx * hidden_size);

    int num_float4 = hidden_size / 4;
    for (int i = tid; i < num_float4; i += blockDim.x) {
        dst_x[i] = src_x[i];
    }

    // Handle remaining floats if hidden_size is not a multiple of 4
    for (int i = tid + num_float4 * 4; i < hidden_size; i += blockDim.x) {
        reordered_x[(int64_t)instance_idx * hidden_size + i] = x[(int64_t)token_idx * hidden_size + i];
    }

    if (tid == 0) {
        reordered_weights[instance_idx] = weights_flat[instance_info_idx];
    }
}

__global__ void fused_silu_mul_vectorized(
    const float* __restrict__ combined_out,
    float* __restrict__ out,
    int num_tokens,
    int intermediate_size
) {
    int token_idx = blockIdx.x;
    int tid = threadIdx.x;

    const float4* gate_ptr = (const float4*)(combined_out + (int64_t)token_idx * 2 * intermediate_size);
    const float4* up_ptr = (const float4*)(combined_out + (int64_t)token_idx * 2 * intermediate_size + intermediate_size);
    float4* dst_ptr = (float4*)(out + (int64_t)token_idx * intermediate_size);

    int num_float4 = intermediate_size / 4;
    for (int i = tid; i < num_float4; i += blockDim.x) {
        float4 g = gate_ptr[i];
        float4 u = up_ptr[i];

        float4 res;
        res.x = (g.x / (1.0f + expf(-g.x))) * u.x;
        res.y = (g.y / (1.0f + expf(-g.y))) * u.y;
        res.z = (g.z / (1.0f + expf(-g.z))) * u.z;
        res.w = (g.w / (1.0f + expf(-g.w))) * u.w;

        dst_ptr[i] = res;
    }

    // Remaining floats
    for (int i = tid + num_float4 * 4; i < intermediate_size; i += blockDim.x) {
        float g = combined_out[(int64_t)token_idx * 2 * intermediate_size + i];
        float u = combined_out[(int64_t)token_idx * 2 * intermediate_size + intermediate_size + i];
        out[(int64_t)token_idx * intermediate_size + i] = (g / (1.0f + expf(-g))) * u;
    }
}

__global__ void weighted_scatter_vectorized(
    const float* __restrict__ expert_out,
    const int64_t* __restrict__ token_instance_indices,
    const float* __restrict__ reordered_weights,
    float* __restrict__ final_out,
    int hidden_size,
    int top_k,
    int num_token_instances
) {
    int instance_idx = blockIdx.x;
    int tid = threadIdx.x;

    int64_t instance_info_idx = token_instance_indices[instance_idx];
    int token_idx = (int)(instance_info_idx / top_k);
    float weight = reordered_weights[instance_idx];

    const float4* src = (const float4*)(expert_out + (int64_t)instance_idx * hidden_size);
    float* dst = final_out + (int64_t)token_idx * hidden_size;

    int num_float4 = hidden_size / 4;
    for (int i = tid; i < num_float4; i += blockDim.x) {
        float4 val = src[i];
        atomicAdd(dst + i * 4 + 0, val.x * weight);
        atomicAdd(dst + i * 4 + 1, val.y * weight);
        atomicAdd(dst + i * 4 + 2, val.z * weight);
        atomicAdd(dst + i * 4 + 3, val.w * weight);
    }

    // Remaining floats
    for (int i = tid + num_float4 * 4; i < hidden_size; i += blockDim.x) {
        atomicAdd(dst + i, expert_out[(int64_t)instance_idx * hidden_size + i] * weight);
    }
}

void reorder_tokens_hip(
    torch::Tensor x,
    torch::Tensor token_instance_indices,
    torch::Tensor weights_flat,
    torch::Tensor reordered_x,
    torch::Tensor reordered_weights,
    int top_k
) {
    int num_token_instances = token_instance_indices.size(0);
    int hidden_size = x.size(1);

    reorder_tokens_vectorized<<<num_token_instances, 256>>>(
        x.data_ptr<float>(),
        token_instance_indices.data_ptr<int64_t>(),
        weights_flat.data_ptr<float>(),
        reordered_x.data_ptr<float>(),
        reordered_weights.data_ptr<float>(),
        hidden_size,
        top_k,
        num_token_instances
    );
}

void fused_silu_mul_hip(
    torch::Tensor combined_out,
    torch::Tensor out
) {
    int num_tokens = combined_out.size(0);
    int intermediate_size = out.size(1);

    fused_silu_mul_vectorized<<<num_tokens, 256>>>(
        combined_out.data_ptr<float>(),
        out.data_ptr<float>(),
        num_tokens,
        intermediate_size
    );
}

void weighted_scatter_hip(
    torch::Tensor expert_out,
    torch::Tensor token_instance_indices,
    torch::Tensor reordered_weights,
    torch::Tensor final_out,
    int top_k
) {
    int num_token_instances = token_instance_indices.size(0);
    int hidden_size = final_out.size(1);

    weighted_scatter_vectorized<<<num_token_instances, 256>>>(
        expert_out.data_ptr<float>(),
        token_instance_indices.data_ptr<int64_t>(),
        reordered_weights.data_ptr<float>(),
        final_out.data_ptr<float>(),
        hidden_size,
        top_k,
        num_token_instances
    );
}
"""

moe_kernels = load_inline(
    name="moe_kernels_v2",
    cpp_sources=moe_gated_gemm_kernels_code,
    functions=[
        "reorder_tokens_hip",
        "fused_silu_mul_hip",
        "weighted_scatter_hip",
    ],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, hidden_size, intermediate_size, num_experts):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.num_experts = num_experts

        self.gate_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(num_experts, hidden_size, intermediate_size) * 0.02
        )

        # Combine gate and up weights for faster GEMM
        self.combined_weights = nn.Parameter(torch.cat([self.gate_proj, self.up_proj], dim=1))

    def forward(self, x, expert_indices, expert_weights):
        batch_size, seq_len, _ = x.shape
        top_k = expert_indices.shape[-1]
        num_tokens = batch_size * seq_len
        num_token_instances = num_tokens * top_k

        x_flat = x.view(num_tokens, self.hidden_size)
        expert_indices_flat = expert_indices.view(-1)
        expert_weights_flat = expert_weights.view(-1)

        # 1. Sort token-expert instances by expert_idx
        token_instance_indices = expert_indices_flat.argsort()
        sorted_expert_indices = expert_indices_flat[token_instance_indices]

        # 2. Reorder tokens and weights
        reordered_x = torch.empty(num_token_instances, self.hidden_size, device=x.device, dtype=x.dtype)
        reordered_weights = torch.empty(num_token_instances, device=x.device, dtype=x.dtype)

        moe_kernels.reorder_tokens_hip(
            x_flat,
            token_instance_indices,
            expert_weights_flat,
            reordered_x,
            reordered_weights,
            top_k
        )

        # 3. Find expert offsets
        expert_counts = torch.bincount(sorted_expert_indices, minlength=self.num_experts)
        expert_offsets = torch.cumsum(expert_counts, dim=0) - expert_counts

        # 4. Prepare output tensor
        final_output = torch.zeros(num_tokens, self.hidden_size, device=x.device, dtype=x.dtype)

        # 5. Loop through experts
        expert_counts_list = expert_counts.cpu().tolist()
        expert_offsets_list = expert_offsets.cpu().tolist()

        for i in range(self.num_experts):
            count = expert_counts_list[i]
            if count == 0:
                continue

            offset = expert_offsets_list[i]
            expert_tokens = reordered_x[offset : offset + count]

            # Gated GEMM
            # combined_proj: (2 * intermediate_size, hidden_size)
            combined_out = F.linear(expert_tokens, self.combined_weights[i])

            # Fused SiLU and Mul
            intermediate = torch.empty(count, self.intermediate_size, device=x.device, dtype=x.dtype)
            moe_kernels.fused_silu_mul_hip(combined_out, intermediate)

            expert_out = F.linear(intermediate, self.down_proj[i])

            # Weighted Scatter
            moe_kernels.weighted_scatter_hip(
                expert_out,
                token_instance_indices[offset : offset + count],
                reordered_weights[offset : offset + count],
                final_output,
                top_k
            )

        return final_output.view(batch_size, seq_len, self.hidden_size)

def get_inputs():
    batch_size = 4
    seq_len = 2048
    hidden_size = 4096
    num_experts = 8
    top_k = 2
    x = torch.randn(batch_size, seq_len, hidden_size).cuda()
    expert_indices = torch.stack([
        torch.randperm(num_experts)[:top_k]
        for _ in range(batch_size * seq_len)
    ]).view(batch_size, seq_len, top_k).cuda()
    expert_weights = F.softmax(torch.randn(batch_size, seq_len, top_k), dim=-1).cuda()
    return [x, expert_indices, expert_weights]

