gemm_int4_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <hip/hip_fp16.h>

__global__ void __launch_bounds__(256) gemm_int4_v3(
    const __half* __restrict__ A,
    const uint8_t* __restrict__ B_packed,
    const __half* __restrict__ scales,
    __half* __restrict__ C,
    int M, int N, int K, int group_size
) {
    const int BM = 128;
    const int BN = 128;
    const int BK = 32;

    __shared__ __half sA[BM][BK];
    __shared__ __half sB[BN][BK];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int tid = ty * 16 + tx; // 0 to 255

    float acc[8][8];
    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            acc[i][j] = 0.0f;
        }
    }

    int num_groups = K / group_size;
    int row_start = by * BM;
    int col_start = bx * BN;

    for (int k_tile = 0; k_tile < K; k_tile += BK) {
        // Load A into sA: 128 rows, 32 cols. Total 4096 elements.
        // tid: 0-255. Each tid loads 4096/256 = 16 elements.
        // Using float4 (8 halves) - 2 float4 per thread.
        for (int i = 0; i < 2; ++i) {
            int load_idx = tid * 16 + i * 8;
            int r = load_idx / 32;
            int c = load_idx % 32;
            int a_row = row_start + r;
            int a_col = k_tile + c;

            if (a_row < M && a_col < K) {
                // We use float2 to load 4 halves if possible, or just copy halves.
                // Let's keep it simple and safe for now.
                *((float4*)&sA[r][c]) = *((float4*)&A[a_row * K + a_col]);
            } else {
                *((float4*)&sA[r][c]) = make_float4(0, 0, 0, 0);
            }
        }

        // Load and dequantize B into sB: 128 rows, 32 cols. Total 4096 elements.
        // B_packed has 128 rows, 16 cols. Total 2048 bytes.
        // tid: 0-255. Each tid loads 2048/256 = 8 bytes.
        for (int i = 0; i < 8; ++i) {
            int load_idx = tid * 8 + i; // 0 to 2047
            int r = load_idx / 16;      // row in sB/B_packed (0-127)
            int c_packed = load_idx % 16; // col in B_packed (0-15)

            int n_idx = col_start + r;
            int k_idx = k_tile + c_packed * 2;

            if (n_idx < N && k_idx < K) {
                uint8_t packed_val = B_packed[n_idx * (K / 2) + (k_idx / 2)];
                __half scale = scales[n_idx * num_groups + (k_idx / group_size)];
                float f_scale = (float)scale;

                sB[r][c_packed * 2] = (__half)(f_scale * ((float)(packed_val & 0x0F) - 8.0f));
                sB[r][c_packed * 2 + 1] = (__half)(f_scale * ((float)(packed_val >> 4) - 8.0f));
            } else {
                sB[r][c_packed * 2] = (__half)0.0f;
                sB[r][c_packed * 2 + 1] = (__half)0.0f;
            }
        }

        __syncthreads();

        // Compute: each thread handles 8x8 output
        // Thread (tx, ty) computes acc[0..7][0..7]
        // Corresponding to rows: ty*4, ty*4+1, ty*4+2, ty*4+3, ty*4+64, ... no, let's rethink
        // tx, ty is 16x16. Output is 128x128.
        // Each thread handles 128/16 = 8 rows and 128/16 = 8 columns.
        for (int k = 0; k < BK; ++k) {
            for (int i = 0; i < 8; ++i) {
                float a_val = (float)sA[ty * 8 + i][k];
                for (int j = 0; j < 8; ++j) {
                    acc[i][j] += a_val * (float)sB[tx * 8 + j][k];
                }
            }
        }

        __syncthreads();
    }

    // Store C
    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            int r = row_start + ty * 8 + i;
            int c = col_start + tx * 8 + j;
            if (r < M && c < N) {
                C[r * N + c] = (__half)acc[i][j];
            }
        }
    }
}

torch::Tensor gemm_int4_hip(torch::Tensor x, torch::Tensor weight_packed, torch::Tensor scales, int group_size) {
    int M = x.size(0) * x.size(1);
    int K = x.size(2);
    int N = weight_packed.size(0);

    auto x_reshaped = x.reshape({M, K});
    auto out = torch::empty({M, N}, x.options());

    dim3 block(16, 16);
    dim3 grid((N + 127) / 128, (M + 127) / 128);

    gemm_int4_v3<<<grid, block>>>(
        (__half*)x_reshaped.data_ptr<at::Half>(),
        (uint8_t*)weight_packed.data_ptr<uint8_t>(),
        (__half*)scales.data_ptr<at::Half>(),
        (__half*)out.data_ptr<at::Half>(),
        M, N, K, group_size
    );

    return out.reshape({x.size(0), x.size(1), N});
}
"""

gemm_int4_module = load_inline(
    name="gemm_int4",
    cpp_sources=gemm_int4_cpp_source,
    functions=["gemm_int4_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, K: int, N: int, group_size: int = 128):
        super().__init__()
        self.K = K
        self.N = N
        self.group_size = group_size
        self.num_groups = K // group_size

        self.register_buffer(
            "weight_packed",
            torch.randint(0, 256, (N, K // 2), dtype=torch.uint8)
        )
        self.register_buffer(
            "scales",
            torch.randn(N, self.num_groups, dtype=torch.float16).abs() * 0.1
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
