gemm_int4_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <hip/hip_fp16.h>

__global__ void __launch_bounds__(256) gemm_int4_v3(
    const __half* __restrict__ A,
    const uint8_t* __restrict__ B_packed,
    const __half* __restrict__ scales,
    __half* __restrict__ C,
    int M, int N, int K, int group_size
) {
    const int BM = 128;
    const int BN = 128;
    const int BK = 32;

    __shared__ alignas(16) __half sA[BM][BK];
    __shared__ alignas(16) __half sB[BN][BK];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int tid = ty * 16 + tx;

    float acc[8][8];
    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            acc[i][j] = 0.0f;
        }
    }

    int num_groups = K / group_size;
    int row_start = by * BM;
    int col_start = bx * BN;

    for (int k_tile = 0; k_tile < K; k_tile += BK) {
        // Load A into sA: 128x32
        for (int i = 0; i < 16; i++) {
            // Each thread loads 16 elements. 256 threads * 16 = 4096. Correct.
            // But wait, my previous loop was wrong. Let's fix it.
            int idx = tid * 16 + i;
            int r = idx / 32;
            int c = idx % 32;
            int a_row = row_start + r;
            int a_col = k_tile + c;
            if (a_row < M && a_col < K) {
                sA[r][c] = A[a_row * K + a_col];
            } else {
                sA[r][c] = (__half)0.0f;
            }
        }

        // Load and dequantize B into sB: 128x32.
        // Needs 128*16 = 2048 bytes of B_packed.
        for (int i = 0; i < 8; i++) {
            int idx = tid * 8 + i;
            int r = idx / 16;
            int c_packed = idx % 16;
            int n_idx = col_start + r;
            int k_idx = k_tile + c_packed * 2;
            if (n_idx < N && k_idx < K) {
                uint8_t val = B_packed[n_idx * (K / 2) + (k_idx / 2)];
                __half scale = scales[n_idx * num_groups + (k_idx / group_size)];
                sB[r][c_packed * 2] = (__half)((float)scale * ((float)(val & 0x0F) - 8.0f));
                sB[r][c_packed * 2 + 1] = (__half)((float)scale * ((float)(val >> 4) - 8.0f));
            } else {
                sB[r][c_packed * 2] = (__half)0.0f;
                sB[r][c_packed * 2 + 1] = (__half)0.0f;
            }
        }

        __syncthreads();

        // Compute 8x8 per thread
        for (int k = 0; k < BK; k++) {
            float a_vals[8];
            float b_vals[8];
            for (int i = 0; i < 8; i++) a_vals[i] = (float)sA[ty * 8 + i][k];
            for (int i = 0; i < 8; i++) b_vals[i] = (float)sB[tx * 8 + i][k];
            for (int i = 0; i < 8; i++) {
                for (int j = 0; j < 8; j++) {
                    acc[i][j] += a_vals[i] * b_vals[j];
                }
            }
        }
        __syncthreads();
    }

    // Store C
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            int r = row_start + ty * 8 + i;
            int c = col_start + tx * 8 + j;
            if (r < M && c < N) {
                C[r * N + c] = (__half)acc[i][j];
            }
        }
    }
}

torch::Tensor gemm_int4_hip(torch::Tensor x, torch::Tensor weight_packed, torch::Tensor scales, int group_size) {
    int M = x.size(0) * x.size(1);
    int K = x.size(2);
    int N = weight_packed.size(0);
    auto out = torch::empty({M, N}, x.options());
    dim3 block(16, 16);
    dim3 grid((N + 127) / 128, (M + 127) / 128);
    gemm_int4_v3<<<grid, block>>>(
        (__half*)x.data_ptr<at::Half>(),
        (uint8_t*)weight_packed.data_ptr<uint8_t>(),
        (__half*)scales.data_ptr<at::Half>(),
        (__half*)out.data_ptr<at::Half>(),
        M, N, K, group_size
    );
    return out.reshape({x.size(0), x.size(1), N});
}
