moe_gated_gemm_kernels_code = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void reorder_tokens_vectorized(
    const float* __restrict__ x,
    const int64_t* __restrict__ token_instance_indices,
    const float* __restrict__ weights_flat,
    float* __restrict__ reordered_x,
    float* __restrict__ reordered_weights,
    int hidden_size,
    int top_k,
    int num_token_instances
) {
    int instance_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (instance_idx < num_token_instances) {
        int64_t instance_info_idx = token_instance_indices[instance_idx];
        int token_idx = (int)(instance_info_idx / top_k);

        const float4* src_x = (const float4*)(x + (int64_t)token_idx * hidden_size);
        float4* dst_x = (float4*)(reordered_x + (int64_t)instance_idx * hidden_size);

        int num_float4 = hidden_size / 4;
        for (int i = tid; i < num_float4; i += blockDim.x) {
            dst_x[i] = src_x[i];
        }

        for (int i = tid + num_float4 * 4; i < hidden_size; i += blockDim.x) {
            reordered_x[(int64_t)instance_idx * hidden_size + i] = x[(int64_t)token_idx * hidden_size + i];
        }

        if (tid == 0) {
            reordered_weights[instance_idx] = weights_flat[instance_info_idx];
        }
    }
}

__global__ void fused_silu_mul_vectorized(
    const float* __restrict__ combined_out,
    float* __restrict__ out,
    int num_instances,
    int intermediate_size
) {
    int instance_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (instance_idx < num_instances) {
        const float4* gate_ptr = (const float4*)(combined_out + (int64_t)instance_idx * 2 * intermediate_size);
        const float4* up_ptr = (const float4*)(combined_out + (int64_t)instance_idx * 2 * intermediate_size + intermediate_size);
        float4* dst_ptr = (float4*)(out + (int64_t)instance_idx * intermediate_size);

        int num_float4 = intermediate_size / 4;
        for (int i = tid; i < num_float4; i += blockDim.x) {
            float4 g = gate_ptr[i];
            float4 u = up_ptr[i];

            float4 res;
            res.x = (g.x / (1.0f + expf(-g.x))) * u.x;
            res.y = (g.y / (1.0f + expf(-g.y))) * u.y;
            res.z = (g.z / (1.0f + expf(-g.z))) * u.z;
            res.w = (g.w / (1.0f + expf(-g.w))) * u.w;

            dst_ptr[i] = res;
        }

        for (int i = tid + num_float4 * 4; i < intermediate_size; i += blockDim.x) {
            float g = combined_out[(int64_t)instance_idx * 2 * intermediate_size + i];
            float u = combined_out[(int64_t)instance_idx * 2 * intermediate_size + intermediate_size + i];
            out[(int64_t)instance_idx * intermediate_size + i] = (g / (1.0f + expf(-g))) * u;
        }
    }
}

__global__ void weighted_scatter_vectorized(
    const float* __restrict__ expert_out,
    const int64_t* __restrict__ token_instance_indices,
    const float* __restrict__ reordered_weights,
    float* __restrict__ final_out,
    int hidden_size,
    int top_k,
    int num_instances
) {
    int instance_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (instance_idx < num_instances) {
        int64_t instance_info_idx = token_instance_indices[instance_idx];
        int token_idx = (int)(instance_info_idx / top_k);
        float weight = reordered_weights[instance_idx];

        const float4* src = (const float4*)(expert_out + (int64_t)instance_idx * hidden_size);
        float* dst = final_out + (int64_t)token_idx * hidden_size;

        int num_float4 = hidden_size / 4;
        for (int i = tid; i < num_float4; i += blockDim.x) {
            float4 val = src[i];
            atomicAdd(dst + i * 4 + 0, val.x * weight);
            atomicAdd(dst + i * 4 + 1, val.y * weight);
            atomicAdd(dst + i * 4 + 2, val.z * weight);
            atomicAdd(dst + i * 4 + 3, val.w * weight);
        }

        for (int i = tid + num_float4 * 4; i < hidden_size; i += blockDim.x) {
            atomicAdd(dst + i, expert_out[(int64_t)instance_idx * hidden_size + i] * weight);
        }
    }
}

void reorder_tokens_hip(
    torch::Tensor x,
    torch::Tensor token_instance_indices,
    torch::Tensor weights_flat,
    torch::Tensor reordered_x,
    torch::Tensor reordered_weights,
    int top_k
) {
    int num_token_instances = token_instance_indices.size(0);
    int hidden_size = x.size(1);
    reorder_tokens_vectorized<<<num_token_instances, 256>>>(
        x.data_ptr<float>(),
        token_instance_indices.data_ptr<int64_t>(),
        weights_flat.data_ptr<float>(),
        reordered_x.data_ptr<float>(),
        reordered_weights.data_ptr<float>(),
        hidden_size,
        top_k,
        num_token_instances
    );
}

void fused_silu_mul_hip(
    torch::Tensor combined_out,
    torch::Tensor out
) {
    int num_instances = combined_out.size(0);
    int intermediate_size = out.size(1);
    fused_silu_mul_vectorized<<<num_instances, 256>>>(
        combined_out.data_ptr<float>(),
        out.data_ptr<float>(),
        num_instances,
        intermediate_size
    );
}

void weighted_scatter_hip(
    torch::Tensor expert_out,
    torch::Tensor token_instance_indices,
    torch::Tensor reordered_weights,
    torch::Tensor final_out,
    int top_k
) {
    int num_instances = expert_out.size(0);
    int hidden_size = final_out.size(1);
    weighted_scatter_vectorized<<<num_instances, 256>>>(
        expert_out.data_ptr<float>(),
        token_instance_indices.data_ptr<int64_t>(),
        reordered_weights.data_ptr<float>(),
        final_out.data_ptr<float>(),
        hidden_size,
        top_k,
        num_instances
    );
}
"""

moe_kernels = load_inline(
    name="moe_kernels_v3",
    cpp_sources=moe_gated_gemm_kernels_code,
    functions=[
        "reorder_tokens_hip",
