class ModelNew(nn.Module):
    def __init__(self, hidden_size, intermediate_size, num_experts):
        super().__init__()
        self.hidden_size = hidden_size
        self.intermediate_size = intermediate_size
        self.num_experts = num_experts

        self.gate_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.up_proj = nn.Parameter(
            torch.randn(num_experts, intermediate_size, hidden_size) * 0.02
        )
        self.down_proj = nn.Parameter(
            torch.randn(num_experts, hidden_size, intermediate_size) * 0.02
        )

        self.combined_weights = nn.Parameter(torch.cat([self.gate_proj, self.up_proj], dim=1))

    def forward(self, x, expert_indices, expert_weights):
        batch_size, seq_len, _ = x.shape
        top_k = expert_indices.shape[-1]
        num_tokens = batch_size * seq_len
        num_token_instances = num_tokens * top_k

        x_flat = x.view(num_tokens, self.hidden_size)
        expert_indices_flat = expert_indices.view(-1)
        expert_weights_flat = expert_weights.view(-1)

        token_instance_indices = expert_indices_flat.argsort()
        sorted_expert_indices = expert_indices_flat[token_instance_indices]

        reordered_x = torch.empty(num_token_instances, self.hidden_size, device=x.device, dtype=x.dtype)
        reordered_weights = torch.empty(num_token_instances, device=x.device, dtype=x.dtype)

        moe_kernels.reorder_tokens_hip(
            x_flat,
            token_instance_indices,
            expert_weights_flat,
            reordered_x,
            reordered_weights,
            top_k
        )

        expert_counts = torch.bincount(sorted_expert_indices, minlength=self.num_experts)
        max_count = expert_counts.max().item()

        # Padding tokens to use torch.bmm
        padded_x = torch.zeros(self.num_experts, max_count, self.hidden_size, device=x.device, dtype=x.dtype)

        # We need a kernel to fill padded_x efficiently
        # But let's see if we can just use a loop for now, or use some other trick.
        expert_offsets = torch.cumsum(expert_counts, dim=0) - expert_counts
        expert_offsets_list = expert_offsets.cpu().tolist()
        expert_counts_list = expert_counts.cpu().tolist()

        for i in range(self.num_experts):
            if expert_counts_list[i] > 0:
                padded_x[i, :expert_counts_list[i]] = reordered_x[expert_offsets_list[i] : expert_offsets_list[i] + expert_counts_list[i]]

        # GEMM 1: (num_experts, max_count, 2*intermediate_size)
        combined_out = torch.bmm(padded_x, self.combined_weights.transpose(1, 2))

        # Fused SiLU & Mul
        # We need to handle padding here too, but the fused_silu_mul doesn't care about padding
        # as long as we only use the valid parts later.
        intermediate = torch.empty(self.num_experts, max_count, self.intermediate_size, device=x.device, dtype=x.dtype)
        moe_kernels.fused_silu_mul_hip(combined_out.view(-1, 2 * self.intermediate_size), intermediate.view(-1, self.intermediate_size))

        # GEMM 2: (num_experts, max_count, hidden_size)
        expert_out_padded = torch.bmm(intermediate, self.down_proj.transpose(1, 2))

        # Final weighted scatter
        # We need to only scatter the valid (non-padded) parts.
        final_output = torch.zeros(num_tokens, self.hidden_size, device=x.device, dtype=x.dtype)

        for i in range(self.num_experts):
            if expert_counts_list[i] > 0:
                count = expert_counts_list[i]
                offset = expert_offsets_list[i]
                moe_kernels.weighted_scatter_hip(
                    expert_out_padded[i, :count],
                    token_instance_indices[offset : offset + count],
                    reordered_weights[offset : offset + count],
                    final_output,
                    top_k
                )

        return final_output.view(batch_size, seq_len, self.hidden_size)

def get_inputs():
    batch_size = 4
    seq_len = 2048
    hidden_size = 4096
    num_experts = 8
    top_k = 2
    x = torch.randn(batch_size, seq_len, hidden_size).cuda()
    expert_indices = torch.stack([
        torch.randperm(num_experts)[:top_k]
        for _ in range(batch_size * seq_len)
    ]).view(batch_size, seq_len, top_k).cuda()
    expert_weights = F.softmax(torch.randn(batch_size, seq_len, top_k), dim=-1).cuda()
    return [x, expert_indices, expert_weights]

