import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

rope_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void rope_reshape_kernel(
    const float* __restrict__ qkv_in,   // (bsz, q_len, total_heads * head_dim)
    const float* __restrict__ cos_table, // (q_len, head_dim)
    const float* __restrict__ sin_table, // (q_len, head_dim)
    float* __restrict__ q_out,           // (bsz, n_heads, q_len, head_dim)
    float* __restrict__ k_out,           // (bsz, n_kv_heads, q_len, head_dim)
    float* __restrict__ v_out,           // (bsz, n_kv_heads, q_len, head_dim)
    int bsz, int q_len, int n_heads, int n_kv_heads, int head_dim
) {
    int b = blockIdx.z;
    int q = blockIdx.y;
    int h = blockIdx.x;
    int d = threadIdx.x;

    int total_heads = n_heads + 2 * n_kv_heads;
    int in_idx = ((b * q_len + q) * total_heads + h) * head_dim + d;
    float val = qkv_in[in_idx];

    if (h < n_heads + n_kv_heads) { // Q or K
        int rope_other_d = (d < head_dim / 2) ? d + head_dim / 2 : d - head_dim / 2;
        float val_other = qkv_in[((b * q_len + q) * total_heads + h) * head_dim + rope_other_d];
        float cos_val = cos_table[q * head_dim + d];
        float sin_val = sin_table[q * head_dim + d];

        float res;
        if (d < head_dim / 2) {
            res = val * cos_val - val_other * sin_val;
        } else {
            res = val * cos_val + val_other * sin_val;
        }

        if (h < n_heads) { // Q
            int out_idx = ((b * n_heads + h) * q_len + q) * head_dim + d;
            q_out[out_idx] = res;
        } else { // K
            int out_idx = ((b * n_kv_heads + (h - n_heads)) * q_len + q) * head_dim + d;
            k_out[out_idx] = res;
        }
    } else { // V
        int out_idx = ((b * n_kv_heads + (h - n_heads - n_kv_heads)) * q_len + q) * head_dim + d;
        v_out[out_idx] = val;
    }
}

std::vector<torch::Tensor> rope_reshape_hip(
    torch::Tensor qkv_in, torch::Tensor cos, torch::Tensor sin,
    int n_heads, int n_kv_heads, int head_dim
) {
    int bsz = qkv_in.size(0);
    int q_len = qkv_in.size(1);

    auto q_out = torch::empty({bsz, n_heads, q_len, head_dim}, qkv_in.options());
    auto k_out = torch::empty({bsz, n_kv_heads, q_len, head_dim}, qkv_in.options());
    auto v_out = torch::empty({bsz, n_kv_heads, q_len, head_dim}, qkv_in.options());

    dim3 grid(n_heads + 2 * n_kv_heads, q_len, bsz);
    dim3 block(head_dim);

    rope_reshape_kernel<<<grid, block>>>(
        qkv_in.data_ptr<float>(), cos.data_ptr<float>(), sin.data_ptr<float>(),
        q_out.data_ptr<float>(), k_out.data_ptr<float>(), v_out.data_ptr<float>(),
        bsz, q_len, n_heads, n_kv_heads, head_dim
    );

    return {q_out, k_out, v_out};
}
"""

rope_reshape = load_inline(
    name="rope_reshape",
    cpp_sources=rope_kernel_source,
    functions=["rope_reshape_hip"],
    verbose=True,
)

class RotaryEmbedding(nn.Module):
    def __init__(self, dim, max_position_embeddings=4096, base=10000.0):
        super().__init__()
        self.dim = dim
        self.max_position_embeddings = max_position_embeddings
        self.base = base
        inv_freq = 1.0 / (self.base ** (torch.arange(0, self.dim, 2, dtype=torch.float32) / self.dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    @torch.no_grad()
    def forward(self, x, seq_len=None):
        if seq_len is None:
            seq_len = x.shape[-2]
        t = torch.arange(seq_len, device=x.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        return emb.cos().unsqueeze(0).unsqueeze(0), emb.sin().unsqueeze(0).unsqueeze(0)

class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        num_key_value_heads: int,
        head_dim: int,
        max_position_embeddings: int = 4096,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.num_kv_heads = num_key_value_heads
        self.head_dim = head_dim
        self.num_key_value_groups = num_attention_heads // num_key_value_heads
        self.attention_dropout = attention_dropout
        self.softmax_scale = head_dim ** (-0.5)

        self.qkv_proj = nn.Linear(hidden_size, (num_attention_heads + 2 * num_key_value_heads) * head_dim, bias=False)
        self.o_proj = nn.Linear(num_attention_heads * head_dim, hidden_size, bias=False)

        self.rotary_emb = RotaryEmbedding(
            head_dim,
            max_position_embeddings=max_position_embeddings,
            base=rope_theta,
        )

    def repeat_kv(self, hidden_states: torch.Tensor, n_rep: int) -> torch.Tensor:
        if n_rep == 1:
            return hidden_states
        batch, num_kv_heads, seq_len, head_dim = hidden_states.shape
        hidden_states = hidden_states[:, :, None, :, :].expand(
            batch, num_kv_heads, n_rep, seq_len, head_dim
        )
        return hidden_states.reshape(batch, num_kv_heads * n_rep, seq_len, head_dim)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        bsz, q_len, _ = hidden_states.size()

        qkv_output = self.qkv_proj(hidden_states)

        cos, sin = self.rotary_emb(qkv_output, seq_len=q_len)
        cos = cos.squeeze(0).squeeze(0)
        sin = sin.squeeze(0).squeeze(0)

        query_states, key_states, value_states = rope_reshape.rope_reshape_hip(
            qkv_output, cos, sin, self.num_heads, self.num_kv_heads, self.head_dim
        )

        key_states = self.repeat_kv(key_states, self.num_key_value_groups)
        value_states = self.repeat_kv(value_states, self.num_key_value_groups)

        attn_output = F.scaled_dot_product_attention(
            query_states,
            key_states,
            value_states,
            attn_mask=None,
            dropout_p=self.attention_dropout if self.training else 0.0,
            is_causal=True
        )

        attn_output = attn_output.transpose(1, 2).contiguous()
        attn_output = attn_output.reshape(bsz, q_len, self.num_heads * self.head_dim)
        attn_output = self.o_proj(attn_output)

        return attn_output

import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

mla_kernels_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void rms_norm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    float eps,
    int hidden_size,
    int num_elements
) {
    int row_idx = blockIdx.x;
    const float* row_input = input + row_idx * hidden_size;
    float* row_output = output + row_idx * hidden_size;

    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        float val = row_input[i];
        sum_sq += val * val;
    }

    __shared__ float shared_sum_sq[256];
    int tid = threadIdx.x;
    shared_sum_sq[tid] = sum_sq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_sum_sq[tid] += shared_sum_sq[tid + s];
        }
        __syncthreads();
    }

    float inv_rms = rsqrtf(shared_sum_sq[0] / hidden_size + eps);

    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        row_output[i] = row_input[i] * inv_rms * weight[i];
    }
}

torch::Tensor rms_norm_hip(torch::Tensor input, torch::Tensor weight, float eps) {
    int hidden_size = input.size(-1);
    int num_rows = input.numel() / hidden_size;
    auto output = torch::empty_like(input);

    const int block_size = 256;
    rms_norm_kernel<<<num_rows, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        eps,
        hidden_size,
        input.numel()
    );

    return output;
}

__global__ void rope_and_concat_kernel(
    const float* __restrict__ q_nope,
    const float* __restrict__ q_pe,
    const float* __restrict__ k_nope,
    const float* __restrict__ k_pe_in,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    float* __restrict__ out_q,
    float* __restrict__ out_k,
    int bsz, int q_len, int num_heads, int nope_dim, int rope_dim
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int head_dim = nope_dim + rope_dim;
    int total_elements = bsz * num_heads * q_len * head_dim;

    if (idx < total_elements) {
        int d = idx % head_dim;
        int s = (idx / head_dim) % q_len;
        int h = (idx / (head_dim * q_len)) % num_heads;
        int b = idx / (head_dim * q_len * num_heads);

        int out_idx = idx;

        if (d < nope_dim) {
            int in_idx = ((b * q_len + s) * num_heads + h) * nope_dim + d;
            out_q[out_idx] = q_nope[in_idx];
            out_k[out_idx] = k_nope[in_idx];
        } else {
            int rd = d - nope_dim;
            int half_rope = rope_dim / 2;
            int in_idx = ((b * q_len + s) * num_heads + h) * rope_dim + rd;
            int in_k_pe_idx = ((b * q_len + s) * 1 + 0) * rope_dim + rd;

            float q_val = q_pe[in_idx];
            float k_val = k_pe_in[in_k_pe_idx];
            float c = cos[s * rope_dim + rd];
            float s_val = sin[s * rope_dim + rd];

            float q_rotated, k_rotated;
            if (rd < half_rope) {
                float q_other = q_pe[in_idx + half_rope];
                float k_other = k_pe_in[in_k_pe_idx + half_rope];
                q_rotated = q_val * c - q_other * s_val;
                k_rotated = k_val * c - k_other * s_val;
            } else {
                float q_other = q_pe[in_idx - half_rope];
                float k_other = k_pe_in[in_k_pe_idx - half_rope];
                q_rotated = q_val * c + q_other * s_val;
                k_rotated = k_val * c + k_other * s_val;
            }
            out_q[out_idx] = q_rotated;
            out_k[out_idx] = k_rotated;
        }
    }
}

std::vector<torch::Tensor> rope_and_concat_hip(
    torch::Tensor q_nope, torch::Tensor q_pe,
    torch::Tensor k_nope, torch::Tensor k_pe,
    torch::Tensor cos, torch::Tensor sin
) {
    int bsz = q_nope.size(0);
    int q_len = q_nope.size(1);
    int num_heads = q_nope.size(2);
    int nope_dim = q_nope.size(3);
    int rope_dim = q_pe.size(3);
    int head_dim = nope_dim + rope_dim;

    auto out_q = torch::empty({bsz, num_heads, q_len, head_dim}, q_nope.options());
    auto out_k = torch::empty({bsz, num_heads, q_len, head_dim}, q_nope.options());

    int total_elements = bsz * num_heads * q_len * head_dim;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    rope_and_concat_kernel<<<num_blocks, block_size>>>(
        q_nope.data_ptr<float>(),
        q_pe.data_ptr<float>(),
        k_nope.data_ptr<float>(),
        k_pe.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        out_q.data_ptr<float>(),
        out_k.data_ptr<float>(),
        bsz, q_len, num_heads, nope_dim, rope_dim
    );

    return {out_q, out_k};
}
"""

mla_kernels = load_inline(
    name="mla_kernels_v2",
    cpp_sources=mla_kernels_source,
    functions=["rms_norm_hip", "rope_and_concat_hip"],
    verbose=True,
)

class DeepSeekRMSNormNew(nn.Module):
    def __init__(self, hidden_size, eps=1e-6):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states):
        return mla_kernels.rms_norm_hip(hidden_states.float(), self.weight.float(), self.variance_epsilon).to(hidden_states.dtype)

class ModelNew(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        num_attention_heads: int,
        q_lora_rank: int,
        kv_lora_rank: int,
        qk_nope_head_dim: int,
        qk_rope_head_dim: int,
        v_head_dim: int,
        max_position_embeddings: int = 2048,
        rope_theta: float = 10000.0,
        attention_dropout: float = 0.0,
    ):
        super().__init__()
        self.hidden_size = hidden_size
        self.num_heads = num_attention_heads
        self.q_lora_rank = q_lora_rank
        self.kv_lora_rank = kv_lora_rank
        self.qk_nope_head_dim = qk_nope_head_dim
        self.qk_rope_head_dim = qk_rope_head_dim
        self.v_head_dim = v_head_dim
        self.q_head_dim = qk_nope_head_dim + qk_rope_head_dim
        self.attention_dropout = attention_dropout
        self.softmax_scale = self.q_head_dim ** (-0.5)

        self.q_a_proj = nn.Linear(hidden_size, q_lora_rank, bias=False)
        self.q_a_layernorm = DeepSeekRMSNormNew(q_lora_rank)
        self.q_b_proj = nn.Linear(q_lora_rank, num_attention_heads * self.q_head_dim, bias=False)

        self.kv_a_proj_with_mqa = nn.Linear(hidden_size, kv_lora_rank + qk_rope_head_dim, bias=False)
        self.kv_a_layernorm = DeepSeekRMSNormNew(kv_lora_rank)
        self.kv_b_proj = nn.Linear(kv_lora_rank, num_attention_heads * (qk_nope_head_dim + v_head_dim), bias=False)
        self.o_proj = nn.Linear(num_attention_heads * v_head_dim, hidden_size, bias=False)

        inv_freq = 1.0 / (rope_theta ** (torch.arange(0, qk_rope_head_dim, 2, dtype=torch.float32) / qk_rope_head_dim))
        self.register_buffer("inv_freq", inv_freq, persistent=False)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        bsz, q_len, _ = hidden_states.size()

        q_lat = self.q_a_layernorm(self.q_a_proj(hidden_states))
        q = self.q_b_proj(q_lat).view(bsz, q_len, self.num_heads, self.q_head_dim)
        q_nope, q_pe = torch.split(q, [self.qk_nope_head_dim, self.qk_rope_head_dim], dim=-1)

        kv_lat_pe = self.kv_a_proj_with_mqa(hidden_states)
        kv_lat, k_pe = torch.split(kv_lat_pe, [self.kv_lora_rank, self.qk_rope_head_dim], dim=-1)
        k_pe = k_pe.view(bsz, q_len, 1, self.qk_rope_head_dim)

        kv_expanded = self.kv_b_proj(self.kv_a_layernorm(kv_lat)).view(bsz, q_len, self.num_heads, self.qk_nope_head_dim + self.v_head_dim)
        k_nope, value_states = torch.split(kv_expanded, [self.qk_nope_head_dim, self.v_head_dim], dim=-1)

        t = torch.arange(q_len, device=hidden_states.device, dtype=torch.float32)
        freqs = torch.outer(t, self.inv_freq)
        emb = torch.cat((freqs, freqs), dim=-1)
        cos, sin = emb.cos(), emb.sin()

        query_states, key_states = mla_kernels.rope_and_concat_hip(q_nope.float(), q_pe.float(), k_nope.float(), k_pe.float(), cos, sin)

        query_states = query_states.to(hidden_states.dtype)
        key_states = key_states.to(hidden_states.dtype)
        value_states = value_states.transpose(1, 2).to(hidden_states.dtype)

        attn_output = F.scaled_dot_product_attention(
            query_states, key_states, value_states,
            is_causal=True, dropout_p=self.attention_dropout if self.training else 0.0,
            scale=self.softmax_scale
        )

        attn_output = attn_output.transpose(1, 2).reshape(bsz, q_len, self.num_heads * self.v_head_dim)
        return self.o_proj(attn_output)

