gemm_int4_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <hip/hip_fp16.h>

__global__ void __launch_bounds__(256) gemm_int4_v3(
    const __half* __restrict__ A,
    const uint8_t* __restrict__ B_packed,
    const __half* __restrict__ scales,
    __half* __restrict__ C,
    int M, int N, int K, int group_size
) {
    const int BM = 128;
    const int BN = 128;
    const int BK = 32;

    __shared__ __half sA[BM * BK];
    __shared__ __half sB[BN * BK];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * 16 + tx;

    float acc[8][8];
    #pragma unroll
    for (int i = 0; i < 8; ++i) {
        #pragma unroll
        for (int j = 0; j < 8; ++j) {
            acc[i][j] = 0.0f;
        }
    }

    int num_groups = K / group_size;
    int row_start = by * BM;
    int col_start = bx * BN;

    for (int k_tile = 0; k_tile < K; k_tile += BK) {
        // Collaborative load A into sA
        #pragma unroll
        for (int i = 0; i < 16; i++) {
            int idx = tid * 16 + i;
            int r = idx / BK;
            int c = idx % BK;
            int a_row = row_start + r;
            int a_col = k_tile + c;
            if (a_row < M && a_col < K) {
                sA[r * BK + c] = A[a_row * K + a_col];
            } else {
                sA[r * BK + c] = (__half)0.0f;
            }
        }

        // Collaborative load B_packed and dequantize into sB
        #pragma unroll
        for (int i = 0; i < 8; i++) {
            int idx = tid * 8 + i; // 0 to 2047
            int r = idx / (BK / 2); // 0 to 127
            int c_packed = idx % (BK / 2); // 0 to 15
            int n_idx = col_start + r;
            int k_idx = k_tile + c_packed * 2;
            if (n_idx < N && k_idx < K) {
                uint8_t val = B_packed[n_idx * (K / 2) + (k_idx / 2)];
                __half scale = scales[n_idx * num_groups + (k_idx / group_size)];
                float f_scale = (float)scale;
                sB[r * BK + c_packed * 2] = (__half)(f_scale * ((float)(val & 0x0F) - 8.0f));
                sB[r * BK + c_packed * 2 + 1] = (__half)(f_scale * ((float)(val >> 4) - 8.0f));
            } else {
                sB[r * BK + c_packed * 2] = (__half)0.0f;
                sB[r * BK + c_packed * 2 + 1] = (__half)0.0f;
            }
        }

        __syncthreads();

        // Compute
        #pragma unroll
        for (int k = 0; k < BK; k++) {
            float b_vals[8];
            #pragma unroll
            for (int j = 0; j < 8; j++) b_vals[j] = (float)sB[(tx * 8 + j) * BK + k];

            #pragma unroll
            for (int i = 0; i < 8; i++) {
                float a_val = (float)sA[(ty * 8 + i) * BK + k];
                #pragma unroll
                for (int j = 0; j < 8; j++) {
                    acc[i][j] += a_val * b_vals[j];
                }
            }
        }
        __syncthreads();
    }

    // Store C
    #pragma unroll
    for (int i = 0; i < 8; i++) {
        #pragma unroll
        for (int j = 0; j < 8; j++) {
            int r = row_start + ty * 8 + i;
            int c = col_start + tx * 8 + j;
            if (r < M && c < N) {
                C[r * N + c] = (__half)acc[i][j];
            }
        }
    }
}

torch::Tensor gemm_int4_hip(torch::Tensor x, torch::Tensor weight_packed, torch::Tensor scales, int group_size) {
    int M = x.size(0) * x.size(1);
    int K = x.size(2);
    int N = weight_packed.size(0);
    auto out = torch::empty({M, N}, x.options());
    dim3 block(16, 16);
    dim3 grid((N + 127) / 128, (M + 127) / 128);
    gemm_int4_v3<<<grid, block>>>(
        (__half*)x.data_ptr<at::Half>(),
        (uint8_t*)weight_packed.data_ptr<uint8_t>(),
        (__half*)scales.data_ptr<at::Half>(),
        (__half*)out.data_ptr<at::Half>(),
        M, N, K, group_size
    );
    return out.reshape({x.size(0), x.size(1), N});
}
