try:
    import reference
    def fixed_apply_rotary_pos_emb(q, k, cos, sin, position_ids=None, unsqueeze_dim=1):
        # The original code used unsqueeze_dim=1 which caused [q_len, 1, head_dim]
        # We need [1, 1, q_len, head_dim] to broadcast with [bsz, num_heads, q_len, head_dim]
        cos = cos.unsqueeze(0).unsqueeze(1)
        sin = sin.unsqueeze(0).unsqueeze(1)

        def rotate_half(x):
            x1 = x[..., : x.shape[-1] // 2]
            x2 = x[..., x.shape[-1] // 2 :]
            return torch.cat((-x2, x1), dim=-1)

        q_embed = (q * cos) + (rotate_half(q) * sin)
        k_embed = (k * cos) + (rotate_half(k) * sin)
        return q_embed, k_embed

    reference.apply_rotary_pos_emb = fixed_apply_rotary_pos_emb
