gemm_int4_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <hip/hip_fp16.h>

__global__ void __launch_bounds__(256) gemm_int4_v4(
    const __half* __restrict__ A,
    const uint8_t* __restrict__ B_packed,
    const __half* __restrict__ scales,
    __half* __restrict__ C,
    int M, int N, int K, int group_size
) {
    const int BM = 128;
    const int BN = 128;
    const int BK = 32;

    __shared__ __half sA[BK][BM + 8]; 
    __shared__ __half sB[BK][BN + 8];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * 16 + tx;

    float acc[8][8];
    #pragma unroll
    for (int i = 0; i < 8; ++i) {
        #pragma unroll
        for (int j = 0; j < 8; ++j) {
            acc[i][j] = 0.0f;
        }
    }

    int num_groups = K / group_size;
    int row_start = by * BM;
    int col_start = bx * BN;

    for (int k_tile = 0; k_tile < K; k_tile += BK) {
        // Coalesced load A: BM x BK = 128 x 32 = 4096 halves
        // 256 threads, each loads 16 halves = 2 float4
        #pragma unroll
        for (int i = 0; i < 2; i++) {
            int idx = tid * 16 + i * 8;
            int r = idx / BK;
            int c = idx % BK;
            int a_row = row_start + r;
            int a_col = k_tile + c;
            if (a_row < M && a_col < K) {
                // Load and store transposed
                sA[c][r] = A[a_row * K + a_col];
                sA[c+1][r] = A[a_row * K + a_col + 1];
                sA[c+2][r] = A[a_row * K + a_col + 2];
                sA[c+3][r] = A[a_row * K + a_col + 3];
                sA[c+4][r] = A[a_row * K + a_col + 4];
                sA[c+5][r] = A[a_row * K + a_col + 5];
                sA[c+6][r] = A[a_row * K + a_col + 6];
                sA[c+7][r] = A[a_row * K + a_col + 7];
            } else {
                #pragma unroll
                for(int k=0; k<8; k++) sA[c+k][r] = (__half)0.0f;
            }
        }
        // Actually, the above is not quite right because of the transpose. 
        // Let's just do it simple but coalesced.

        // Let's use a simpler coalesced load.
        #pragma unroll
        for (int i = 0; i < 16; i++) {
            int idx = tid + i * 256; // 0 to 4095
            int r = idx / BK;
            int c = idx % BK;
            if (row_start + r < M && k_tile + c < K)
                sA[c][r] = A[(row_start + r) * K + (k_tile + c)];
            else
                sA[c][r] = (__half)0.0f;
        }

        // Coalesced load B_packed: BN x BK/2 = 128 x 16 = 2048 bytes
        // 256 threads, each loads 8 bytes.
        #pragma unroll
        for (int i = 0; i < 8; i++) {
            int idx = tid * 8 + i; // 0 to 2047
            int r = idx / 16;
            int c_packed = idx % 16;
            int n_idx = col_start + r;
            int k_idx = k_tile + c_packed * 2;
            if (n_idx < N && k_idx < K) {
                uint8_t val = B_packed[n_idx * (K/2) + (k_idx / 2)];
                __half scale = scales[n_idx * num_groups + (k_idx / group_size)];
                sB[c_packed * 2][r] = (__half)((float)scale * ((float)(val & 0x0F) - 8.0f));
                sB[c_packed * 2 + 1][r] = (__half)((float)scale * ((float)(val >> 4) - 8.0f));
            } else {
                sB[c_packed * 2][r] = (__half)0.0f;
                sB[c_packed * 2 + 1][r] = (__half)0.0f;
            }
        }

        __syncthreads();

        // Compute
        #pragma unroll
        for (int k = 0; k < BK; k++) {
            float a_vals[8];
            float b_vals[8];
            #pragma unroll
            for (int i = 0; i < 8; i++) a_vals[i] = (float)sA[k][ty * 8 + i];
            #pragma unroll
            for (int i = 0; i < 8; i++) b_vals[i] = (float)sB[k][tx * 8 + i];

            #pragma unroll
            for (int i = 0; i < 8; i++) {
                #pragma unroll
                for (int j = 0; j < 8; j++) {
                    acc[i][j] += a_vals[i] * b_vals[j];
                }
            }
        }
        __syncthreads();
    }

    // Store C
    #pragma unroll
    for (int i = 0; i < 8; i++) {
        #pragma unroll
        for (int j = 0; j < 8; j++) {
            int r = row_start + ty * 8 + i;
            int c = col_start + tx * 8 + j;
            if (r < M && c < N) {
                C[r * N + c] = (__half)acc[i][j];
            }
        }
    }
}

torch::Tensor gemm_int4_hip(torch::Tensor x, torch::Tensor weight_packed, torch::Tensor scales, int group_size) {
    int M = x.size(0) * x.size(1);
    int K = x.size(2);
    int N = weight_packed.size(0);
    auto out = torch::empty({M, N}, x.options());
    dim3 block(16, 16);
    dim3 grid((N + 127) / 128, (M + 127) / 128);
    gemm_int4_v4<<<grid, block>>>(
        (__half*)x.data_ptr<at::Half>(),
        (uint8_t*)weight_packed.data_ptr<uint8_t>(),
        (__half*)scales.data_ptr<at::Half>(),
        (__half*)out.data_ptr<at::Half>(),
        M, N, K, group_size
    );
    return out.reshape({x.size(0), x.size(1), N});
}
"""

