#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void fused_silu_mul_v5(
    const float* __restrict__ gate_out,
    const float* __restrict__ up_out,
    float* __restrict__ out,
    int total_rows,
    int intermediate_size
) {
    int row_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (row_idx < total_rows) {
        const float4* g_ptr = (const float4*)(gate_out + (int64_t)row_idx * intermediate_size);
        const float4* u_ptr = (const float4*)(up_out + (int64_t)row_idx * intermediate_size);
        float4* d_ptr = (float4*)(out + (int64_t)row_idx * intermediate_size);

        int num_float4 = intermediate_size / 4;
        for (int i = tid; i < num_float4; i += blockDim.x) {
            float4 g = g_ptr[i];
            float4 u = u_ptr[i];
            float4 res;
            res.x = (g.x / (1.0f + expf(-g.x))) * u.x;
            res.y = (g.y / (1.0f + expf(-g.y))) * u.y;
            res.z = (g.z / (1.0f + expf(-g.z))) * u.z;
            res.w = (g.w / (1.0f + expf(-g.w))) * u.w;
            d_ptr[i] = res;
        }
    }
}

__global__ void weighted_scatter_v5(
    const float* __restrict__ expert_out,
    const int64_t* __restrict__ token_indices,
    const float* __restrict__ weights,
    float* __restrict__ final_out,
    int hidden_size,
    int num_rows
) {
    int row_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (row_idx < num_rows) {
        int64_t token_idx = token_indices[row_idx];
        float w = weights[row_idx];

        const float4* src = (const float4*)(expert_out + (int64_t)row_idx * hidden_size);
        float* dst = final_out + (int64_t)token_idx * hidden_size;

        int num_float4 = hidden_size / 4;
        for (int i = tid; i < num_float4; i += blockDim.x) {
            float4 v = src[i];
            atomicAdd(dst + i*4 + 0, v.x * w);
            atomicAdd(dst + i*4 + 1, v.y * w);
            atomicAdd(dst + i*4 + 2, v.z * w);
            atomicAdd(dst + i*4 + 3, v.w * w);
        }
    }
}

void fused_silu_mul_hip(torch::Tensor gate_out, torch::Tensor up_out, torch::Tensor out) {
    fused_silu_mul_v5<<<gate_out.size(0), 256>>>(gate_out.data_ptr<float>(), up_out.data_ptr<float>(), out.data_ptr<float>(), gate_out.size(0), gate_out.size(1));
