    weighted_scatter_v5<<<expert_out.size(0), 256>>>(expert_out.data_ptr<float>(), indices.data_ptr<int64_t>(), weights.data_ptr<float>(), final_out.data_ptr<float>(), final_out.size(1), expert_out.size(0));
