__global__ void swiglu_kernel(const float* gate, const float* up, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float g = gate[idx];
        float u = up[idx];
        out[idx] = (g / (1.0f + expf(-g))) * u;
    }
