dequant_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <hip/hip_fp16.h>

__global__ void fast_dequant_kernel(
    const uint8_t* __restrict__ weight_packed,
    const __half* __restrict__ scales,
    __half* __restrict__ w_dequant,
    int N, int K, int group_size
) {
    int n = blockIdx.y * blockDim.y + threadIdx.y;
    int k_half = blockIdx.x * blockDim.x + threadIdx.x;

    if (n < N && k_half < K / 2) {
        uint8_t val = weight_packed[n * (K / 2) + k_half];
        int k0 = k_half * 2;
        int k1 = k0 + 1;
        int num_groups = K / group_size;

        float s0 = (float)scales[n * num_groups + (k0 / group_size)];
        float s1 = (float)scales[n * num_groups + (k1 / group_size)];

        w_dequant[n * K + k0] = (__half)(s0 * ((float)(val & 0x0F) - 8.0f));
        w_dequant[n * K + k1] = (__half)(s1 * ((float)(val >> 4) - 8.0f));
    }
}

torch::Tensor dequantize_hip(torch::Tensor weight_packed, torch::Tensor scales, int group_size) {
    int N = weight_packed.size(0);
    int K = weight_packed.size(1) * 2;
    auto w_dequant = torch::empty({N, K}, scales.options());

    dim3 block(256, 1);
    dim3 grid((K / 2 + 255) / 256, N);

    fast_dequant_kernel<<<grid, block>>>(
        (uint8_t*)weight_packed.data_ptr<uint8_t>(),
        (__half*)scales.data_ptr<at::Half>(),
        (__half*)w_dequant.data_ptr<at::Half>(),
        N, K, group_size
    );

    return w_dequant;
}
"""

dequant_module = load_inline(
    name="dequant_module",
    cpp_sources=dequant_cpp_source,
    functions=["dequantize_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, K: int, N: int, group_size: int = 128):
        super().__init__()
        self.K = K
        self.N = N
        self.group_size = group_size
        self.num_groups = K // group_size
        self.register_buffer("weight_packed", torch.randint(0, 256, (N, K // 2), dtype=torch.uint8))
        self.register_buffer("scales", torch.randn(N, self.num_groups, dtype=torch.float16).abs() * 0.1)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        w_dequant = dequant_module.dequantize_hip(self.weight_packed, self.scales, self.group_size)

        batch_size, seq_len, _ = x.shape
        x_2d = x.view(-1, self.K)
        out = torch.matmul(x_2d, w_dequant.T)
        return out.view(batch_size, seq_len, self.N)

