moe_gated_gemm_kernels_code = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void fused_silu_mul_v6(
    const float* __restrict__ gate_out,
    const float* __restrict__ up_out,
    float* __restrict__ out,
    int total_rows,
    int intermediate_size
) {
    int row_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int size = total_rows * intermediate_size;
    if (row_idx < size) {
        float g = gate_out[row_idx];
        float u = up_out[row_idx];
        out[row_idx] = (g / (1.0f + expf(-g))) * u;
    }
}

__global__ void weighted_scatter_v6(
    const float* __restrict__ expert_out,
    const int64_t* __restrict__ token_indices,
    const float* __restrict__ weights,
    float* __restrict__ final_out,
    int hidden_size,
    int num_rows
) {
    int row_idx = blockIdx.x;
    int tid = threadIdx.x;
    if (row_idx < num_rows) {
        int64_t token_idx = token_indices[row_idx];
        float w = weights[row_idx];
        const float* src = expert_out + (int64_t)row_idx * hidden_size;
        float* dst = final_out + (int64_t)token_idx * hidden_size;
        for (int i = tid; i < hidden_size; i += blockDim.x) {
            atomicAdd(dst + i, src[i] * w);
        }
    }
}

void fused_silu_mul_hip(torch::Tensor gate_out, torch::Tensor up_out, torch::Tensor out) {
    int size = gate_out.numel();
    fused_silu_mul_v6<<<(size + 256 - 1) / 256, 256>>>(gate_out.data_ptr<float>(), up_out.data_ptr<float>(), out.data_ptr<float>(), gate_out.size(0), gate_out.size(1));
}

void weighted_scatter_hip(torch::Tensor expert_out, torch::Tensor indices, torch::Tensor weights, torch::Tensor final_out) {
    weighted_scatter_v6<<<expert_out.size(0), 256>>>(expert_out.data_ptr<float>(), indices.data_ptr<int64_t>(), weights.data_ptr<float>(), final_out.data_ptr<float>(), final_out.size(1), expert_out.size(0));
}
"""

moe_kernels = load_inline(
    name="moe_kernels_v6",
    cpp_sources=moe_gated_gemm_kernels_code,
