dequant_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <hip/hip_fp16.h>

__global__ void fast_dequant_kernel_v2(
    const uint8_t* __restrict__ weight_packed,
    const __half* __restrict__ scales,
    __half* __restrict__ w_dequant,
    int N, int K, int group_size
) {
    // Each thread processes 8 weights (4 bytes of weight_packed, 16 bytes of w_dequant)
    int n = blockIdx.y;
    int k_8 = blockIdx.x * blockDim.x + threadIdx.x;

    if (n < N && k_8 * 8 < K) {
        int k_base = k_8 * 8;

        // Load 4 bytes (8 weights)
        uint32_t packed_val = *((uint32_t*)&weight_packed[n * (K / 2) + k_base / 2]);

        // Since group_size is at least 8 (usually 128), all 8 weights belong to the same scale
        // unless k_base is at the boundary. But K is a multiple of group_size.
        // For simplicity, let's just handle it.

        int num_groups = K / group_size;
        float s = (float)scales[n * num_groups + (k_base / group_size)];

        __half2 h2_scale = __float2half2_rn(s);
        __half2 h2_8 = __float2half2_rn(-8.0f);

        __half out[8];
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            uint8_t b = (uint8_t)(packed_val >> (i * 8));
            float f0 = (float)(b & 0x0F) - 8.0f;
            float f1 = (float)(b >> 4) - 8.0f;
            out[i*2] = (__half)(s * f0);
            out[i*2+1] = (__half)(s * f1);
        }

        // Vectorized write 16 bytes (8 halves)
        *((float4*)&w_dequant[n * K + k_base]) = *((float4*)&out[0]);
    }
}

torch::Tensor dequantize_hip(torch::Tensor weight_packed, torch::Tensor scales, int group_size) {
    int N = weight_packed.size(0);
    int K = weight_packed.size(1) * 2;
    auto w_dequant = torch::empty({N, K}, scales.options());

    // Each thread processes 8 weights
    dim3 block(256, 1);
    dim3 grid((K / 8 + 255) / 256, N);

    fast_dequant_kernel_v2<<<grid, block>>>(
        (uint8_t*)weight_packed.data_ptr<uint8_t>(),
        (__half*)scales.data_ptr<at::Half>(),
        (__half*)w_dequant.data_ptr<at::Half>(),
        N, K, group_size
    );

    return w_dequant;
}
"""

